package com.nexvary.imsi;

import android.app.*; import android.os.Bundle; import android.view.WindowManager; import android.widget.*; import java.text.*; import java.util.*;
public class HistoryActivity extends Activity {
    private LinearLayout page; private LocalRepository repo; private boolean ar;
    @Override public void onCreate(Bundle b){ LanguageUtil.apply(this); super.onCreate(b); SecureScreenUtil.apply(this); repo=new LocalRepository(this); ar=LanguageUtil.current(this).equals("ar"); render(); }
    private void render(){ ScrollView s=new ScrollView(this); s.setClipToPadding(false); page=UiKit.page(this); s.addView(page); page.addView(UiKit.eyebrow(this,"NEXVARY · ENCRYPTED LOCAL HISTORY")); page.addView(UiKit.title(this,ar?"سجل الفحوص":"Scan history")); List<ScanRecord> h=repo.history(); if(h.isEmpty()) page.addView(UiKit.body(this,ar?"لا توجد فحوص محفوظة حتى الآن.":"No scans have been saved yet.")); else { SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.getDefault()); for(int i=h.size()-1;i>=0;i--){ ScanRecord r=h.get(i); Button x=UiKit.button(this,f.format(new Date(r.at))+"  ·  "+r.risk+"/100  ·  "+r.radio); x.setOnClickListener(v->show(r)); page.addView(x); } } Button clear=UiKit.button(this,ar?"حذف سجل الفحوص":"CLEAR SCAN HISTORY"); clear.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(ar?"حذف السجل؟":"Clear history?").setMessage(ar?"سيتم حذف سجل الفحوص المشفر فقط، مع الاحتفاظ بخطوط الأساس.":"Encrypted scan history will be deleted; trusted baselines are kept.").setNegativeButton(ar?"إلغاء":"Cancel",null).setPositiveButton(ar?"حذف":"Clear",(d,w)->{repo.clearHistory();render();}).show()); page.addView(clear); setContentView(UiKit.withBottomNav(this,s,2)); }
    private void show(ScanRecord r){ String q=r.quality==-999?"—":r.quality+" dB"; new AlertDialog.Builder(this).setTitle((ar?"تفاصيل الفحص · ":"Scan details · ")+r.risk+"/100").setMessage("Operator: "+r.operator+"\nRadio: "+r.radio+"\nCell: "+r.cell+"\nNeighbors: "+r.neighbors+"\nSignal: "+r.dbm+" dBm\nQuality: "+q+"\nNeighbor fingerprint: "+r.neighborSignature+"\n\n"+(ar?"أسباب التقييم:\n":"Assessment reasons:\n")+(r.reasons==null||r.reasons.isEmpty()?"—":r.reasons.replace(" | ","\n• "))).setPositiveButton(ar?"إغلاق":"Close",null).show(); }
}
